const parts=(v)=>String(v||'').split(/\|\||\r?\n/).map(x=>x.trim()).filter(Boolean);
const broad=computed(()=>item.value.BroadRels||[]); const narrow=computed(()=>item.value.NarrowRels||[]);
</script>
<template><article class="detail-page"><nav class="detail-breadcrumb"><button @click="$router.push('/relations')">{{ t('nav.relations') }}</button><span>/</span><span>{{ item.ID }}</span></nav><header class="detail-hero"><div class="detail-title-row"><span class="detail-code">{{ item.ID }}</span><h1>{{ item.Name }}</h1></div></header>
